
//=======================================================
//  This code is generated by Terasic System Builder
//=======================================================
//
// CAN IDS/IPS on the DE10-Lite: the top level. It only connects the board's
// pins to the modules in hdl/:
//
//   GPIO[0] (CAN RX) -> can_rx -> rf_ids + known_id -> final class -> ips_flag -> GPIO[1] (CAN TX)
//
//   KEY[0]   reset (hold it down)
//   SW[0]    prevention on (up) / off (down): off = listen and classify only
//   LEDR[0]  good frame received          LEDR[1]  attack verdict
//   LEDR[2]  error flag sent              LEDR[3]  CRC / stuff / form error
//   LEDR[9]  prevention is on
//
// Transceiver: a 3.3 V one (SN65HVD230), RX to GPIO[0] (header pin 1),
// TX to GPIO[1] (header pin 2). The DE10-Lite pins are NOT 5 V tolerant.
//
// Model: 6 data bytes (rf5-d9-p6-e7321e76). For another one, change
// FEAT_BYTES below and add hdl/generated_p5 or _p8/rf_ids.v to the project
// instead of hdl/generated_p6/rf_ids.v (all three are called rf_ids).

module can_ids_top(

	//////////// CLOCK //////////
	input 		          		ADC_CLK_10,
	input 		          		MAX10_CLK1_50,
	input 		          		MAX10_CLK2_50,

	//////////// KEY //////////
	input 		     [1:0]		KEY,

	//////////// LED //////////
	output		     [9:0]		LEDR,

	//////////// SW //////////
	input 		     [9:0]		SW,

	//////////// GPIO, GPIO connect to GPIO Default //////////
	inout 		    [35:0]		GPIO
);

	localparam FEAT_BYTES = 6;                // data bytes the model reads
	localparam [63:0] FEAT_MASK = ~(64'hFFFF_FFFF_FFFF_FFFF >> (8 * FEAT_BYTES));
	localparam [22:0] STRETCH = 23'd5_000_000; // LED on time per event: 100 ms at 50 MHz

	wire clk = MAX10_CLK1_50;

//=======================================================
//  a. Reset and prevention switch
//=======================================================
	// KEY and SW change at any time: two flip-flops each (synchronizer).
	reg [1:0] key_s = 2'b11;                  // KEY reads 1 when not pressed
	reg [1:0] sw_s  = 2'b00;
	always @(posedge clk) begin
		key_s <= {key_s[0], KEY[0]};
		sw_s  <= {sw_s[0],  SW[0]};
	end
	wire rst    = ~key_s[1];                   // 1 while KEY[0] is held down
	wire ips_on = sw_s[1];                     // 1 while SW[0] is up

//=======================================================
//  b. CAN receiver
//=======================================================
	wire        frame_valid, crc_err, stuff_err, form_err, feat_ready, before_eof, bit_edge;
	wire [10:0] can_id;
	wire [3:0]  dlc;
	wire [63:0] data;

	can_rx #(.FEAT_BYTES(FEAT_BYTES)) rx (
		.clk(clk), .rst(rst), .rxd(GPIO[0]),
		.frame_valid(frame_valid), .can_id(can_id), .dlc(dlc), .data(data),
		.crc_err(crc_err), .stuff_err(stuff_err), .form_err(form_err),
		.id_ready(), .dlc_ready(), .feat_ready(feat_ready),
		.before_eof(before_eof), .bit_edge(bit_edge)
	);

//=======================================================
//  c. Classifier: forest + unknown ID rule
//=======================================================
	// The forest sees what classify.c gives it: DLC at most 8, only the
	// first FEAT_BYTES data bytes (the rest are not on the bus yet anyway).
	wire       rf_valid;
	wire [2:0] rf_class;
	rf_ids forest (
		.clk(clk), .rst(rst), .in_valid(feat_ready),
		.can_id(can_id), .dlc(dlc > 4'd8 ? 4'd8 : dlc), .data(data & FEAT_MASK),
		.out_valid(rf_valid), .class_out(rf_class)
	);

	// Normal on an ID the car never sent -> Fuzzy (2). can_id still holds
	// this frame's ID when the forest answers, 4 clocks later.
	wire       id_known;
	known_id ids (.can_id(can_id), .known(id_known));
	wire [2:0] final_class = (rf_class == 3'd0 && !id_known) ? 3'd2 : rf_class;

//=======================================================
//  d. IPS: error flag on attack verdicts
//=======================================================
	wire        tx_dominant, flag_start;
	wire [31:0] n_rej, n_ilate, n_allow, n_abort;
	ips_flag ips (
		.clk(clk), .rst(rst), .enable(ips_on),
		.verdict_valid(rf_valid), .verdict(final_class), .can_id(can_id), .data(data),
		.before_eof(before_eof), .bit_edge(bit_edge),
		.tx_dominant(tx_dominant), .flag_start(flag_start),
		.n_rej(n_rej), .n_ilate(n_ilate), .n_allow(n_allow), .n_abort(n_abort)
	);

//=======================================================
//  e. Pins
//=======================================================
	// TX: 1 = recessive (released), 0 = dominant. Driven high from power up,
	// so the board never disturbs the bus unless the IPS flags a frame.
	assign GPIO[1]    = ~tx_dominant;
	assign GPIO[35:2] = 34'bz;                // unused header pins: not driven
	// GPIO[0] is the RX input: not assigned here.

//=======================================================
//  f. LEDs: each event keeps its LED on for 100 ms
//=======================================================
	reg [22:0] led_frame = 0, led_attack = 0, led_flag = 0, led_err = 0;
	always @(posedge clk) begin
		led_frame  <= frame_valid                     ? STRETCH : (led_frame  ? led_frame  - 1'b1 : 23'd0);
		led_attack <= (rf_valid && final_class != 0)  ? STRETCH : (led_attack ? led_attack - 1'b1 : 23'd0);
		led_flag   <= flag_start                      ? STRETCH : (led_flag   ? led_flag   - 1'b1 : 23'd0);
		led_err    <= (crc_err || stuff_err || form_err) ? STRETCH : (led_err ? led_err - 1'b1 : 23'd0);
	end

	assign LEDR[0]   = led_frame  != 0;
	assign LEDR[1]   = led_attack != 0;
	assign LEDR[2]   = led_flag   != 0;
	assign LEDR[3]   = led_err    != 0;
	assign LEDR[8:4] = 5'b0;
	assign LEDR[9]   = ips_on;

endmodule
